import{_ as t,o as c,c as o,a5 as d}from"./chunks/framework.BfQ7H7Qx.js";const y=JSON.parse('{"title":"03 — Công ty, Không gian làm việc & Mẫu cấu hình (Agency & Workspace)","description":"","frontmatter":{},"headers":[],"relativePath":"ba/03-agency-workspace.md","filePath":"ba/03-agency-workspace.md"}'),n={name:"ba/03-agency-workspace.md"};function a(i,e,g,l,r,s){return c(),o("div",null,[...e[0]||(e[0]=[d('<h1 id="_03-—-cong-ty-khong-gian-lam-viec-mau-cau-hinh-agency-workspace" tabindex="-1">03 — Công ty, Không gian làm việc &amp; Mẫu cấu hình (Agency &amp; Workspace) <a class="header-anchor" href="#_03-—-cong-ty-khong-gian-lam-viec-mau-cau-hinh-agency-workspace" aria-label="Permalink to &quot;03 — Công ty, Không gian làm việc &amp; Mẫu cấu hình (Agency &amp; Workspace)&quot;">​</a></h1><p>&gt; Navigation: <a href="./README.html">← BA Overview &amp; Hub</a> · <a href="./02-authentication-profile.html">← 02 - Authentication &amp; Profile</a> · <a href="./04-media-package-campaign.html">Tiếp: 04 - Media Package &amp; Campaign →</a> &gt; &gt; <strong>Phạm vi FR chuẩn</strong> (đồng bộ 100% với <code>Các FR của hệ thống - Feature_Function Requirement.csv</code>): &gt; - <strong>Mục <code>3.4 Agency &amp; Workspace</code></strong>: <strong>26 FR (<code>3.4.1</code> – <code>3.4.26</code>)</strong> | <code>UC-014</code> – <code>UC-039</code> &gt; - Use Cases chi tiết: <a href="./use-cases/02-agency-workspace.html">use-cases/02-agency-workspace.md</a> · Đặc tả SRS: <a href="./../feature/srs/03-agency-workspace/README.html">03-agency-workspace</a></p><hr><h2 id="_1-bang-tong-hop-26-yeu-cau-chuc-nang-chuan-3-4-1-–-3-4-26" tabindex="-1">1. Bảng Tổng hợp 26 Yêu cầu Chức năng Chuẩn (<code>3.4.1</code> – <code>3.4.26</code>) <a class="header-anchor" href="#_1-bang-tong-hop-26-yeu-cau-chuc-nang-chuan-3-4-1-–-3-4-26" aria-label="Permalink to &quot;1. Bảng Tổng hợp 26 Yêu cầu Chức năng Chuẩn (`3.4.1` – `3.4.26`)&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:center;">Mã FR</th><th style="text-align:center;">Mã UC</th><th style="text-align:left;">Tên Chức năng Chuẩn (141-FR Baseline)</th><th style="text-align:left;">Actors / Roles Chuẩn</th><th style="text-align:left;">Mô tả Nghiệp vụ Cốt lõi</th></tr></thead><tbody><tr><td style="text-align:center;"><strong><code>3.4.1</code></strong></td><td style="text-align:center;"><code>UC-014</code></td><td style="text-align:left;"><strong>List Agency</strong></td><td style="text-align:left;"><code>Owner</code>, <code>Manager</code>, <code>Creator</code>, <code>Client</code>, <code>Admin</code></td><td style="text-align:left;">Xem danh sách toàn bộ các Agency mà người dùng đang sở hữu hoặc đang tham gia trên <code>/agencies</code>; hỗ trợ tìm kiếm và lọc <code>Owned</code> / <code>Joined</code> (<code>BR-15</code>, <code>BR-16</code>).</td></tr><tr><td style="text-align:center;"><strong><code>3.4.2</code></strong></td><td style="text-align:center;"><code>UC-015</code></td><td style="text-align:left;"><strong>View Agency Dashboard</strong></td><td style="text-align:left;"><code>Owner</code></td><td style="text-align:left;">Xem bảng điều khiển KPI tổng quan toàn công ty (<code>/agency/:id/dashboard</code>): tổng số Workspace hoạt động, thành viên, tiến độ Media Campaigns và mức tiêu thụ gói cước / AI Credit (<code>BR-15</code>, <code>BR-20</code>).</td></tr><tr><td style="text-align:center;"><strong><code>3.4.3</code></strong></td><td style="text-align:center;"><code>UC-016</code></td><td style="text-align:left;"><strong>Create Agency</strong></td><td style="text-align:left;"><code>Owner</code>, <code>Manager</code>, <code>Creator</code></td><td style="text-align:left;">Khởi tạo một Agency mới trên <code>/agencies/new</code> (hoặc tự động khởi tạo <code>Personal Studio</code> 1 chạm); kiểm tra giới hạn gói cước (<code>BR-58</code>) và gắn cứng <code>owner_id</code> với người tạo duy nhất (<code>BR-15</code>).</td></tr><tr><td style="text-align:center;"><strong><code>3.4.4</code></strong></td><td style="text-align:center;"><code>UC-017</code></td><td style="text-align:left;"><strong>View Agency Profile</strong></td><td style="text-align:left;"><code>Owner</code>, <code>Manager</code>, <code>Creator</code>, <code>Client</code></td><td style="text-align:left;">Xem trang hồ sơ giới thiệu năng lực công ty (<code>/agency/:id/profile</code>) gồm Tên, Logo, Ảnh bìa, Lĩnh vực chuyên môn, Website, Liên hệ và các gói dịch vụ mẫu để <code>Client</code> tham khảo.</td></tr><tr><td style="text-align:center;"><strong><code>3.4.5</code></strong></td><td style="text-align:center;"><code>UC-018</code></td><td style="text-align:left;"><strong>Update Agency Profile</strong></td><td style="text-align:left;"><code>Owner</code></td><td style="text-align:left;">Cập nhật thông tin hồ sơ công ty (<code>/agency/:id/settings</code>): Tên Agency, Mô tả, Website, Địa chỉ, Liên hệ và Logo/Banner mới (<code>BR-12</code>, <code>BR-15</code>).</td></tr><tr><td style="text-align:center;"><strong><code>3.4.6</code></strong></td><td style="text-align:center;"><code>UC-019</code></td><td style="text-align:left;"><strong>Remove Agency</strong></td><td style="text-align:left;"><code>Owner</code></td><td style="text-align:left;">Xóa mềm công ty (<code>Remove Agency</code>) kèm hộp thoại xác nhận tên Agency; chuyển sang <code>INACTIVE</code>/<code>DELETED_PENDING</code>, tạm khóa truy cập Workspace trực thuộc nhưng bảo lưu dữ liệu để khôi phục trong 30 ngày (<code>BR-16</code>).</td></tr><tr><td style="text-align:center;"><strong><code>3.4.7</code></strong></td><td style="text-align:center;"><code>UC-020</code></td><td style="text-align:left;"><strong>Invite Agency Member</strong></td><td style="text-align:left;"><code>Owner</code></td><td style="text-align:left;">Mời thành viên mới gia nhập Agency qua Email và thông báo hệ thống (<code>/agency/:id/members</code>, hỗ trợ chọn ngôn ngữ email <code>vi</code>/<code>en</code> và xem trước mẫu email); lời mời hết hạn sau 30 ngày (<code>BR-17</code>).</td></tr><tr><td style="text-align:center;"><strong><code>3.4.8</code></strong></td><td style="text-align:center;"><code>UC-021</code></td><td style="text-align:left;"><strong>View Agency Invitation Status</strong></td><td style="text-align:left;"><code>Owner</code>, <code>Manager</code>, <code>Creator</code>, <code>Client</code></td><td style="text-align:left;">Theo dõi danh sách và trạng thái các lời mời gia nhập Agency (<code>PENDING</code>, <code>ACCEPTED</code>, <code>DECLINED</code>, <code>EXPIRED</code>) kèm đếm ngược 30 ngày; <code>Owner</code> có thể gửi lại (<code>Resend</code>) hoặc thu hồi lời mời <code>PENDING</code> (<code>BR-17</code>, <code>BR-18</code>).</td></tr><tr><td style="text-align:center;"><strong><code>3.4.9</code></strong></td><td style="text-align:center;"><code>UC-022</code></td><td style="text-align:left;"><strong>Accept Agency Invitation</strong></td><td style="text-align:left;"><code>Owner</code>, <code>Manager</code>, <code>Creator</code>, <code>Client</code></td><td style="text-align:left;">Chấp nhận lời mời gia nhập Agency từ thông báo ứng dụng hoặc liên kết email (<code>/invitations/:token</code>) khi còn hạn 30 ngày (<code>BR-17</code>, <code>BR-18</code>).</td></tr><tr><td style="text-align:center;"><strong><code>3.4.10</code></strong></td><td style="text-align:center;"><code>UC-023</code></td><td style="text-align:left;"><strong>Decline Agency Invitation</strong></td><td style="text-align:left;"><code>Owner</code>, <code>Manager</code>, <code>Creator</code>, <code>Client</code></td><td style="text-align:left;">Từ chối lời mời tham gia Agency (<code>/invitations/:token</code>), chuyển trạng thái lời mời sang <code>DECLINED</code> và thông báo phản hồi cho <code>Owner</code> (<code>BR-17</code>, <code>BR-18</code>).</td></tr><tr><td style="text-align:center;"><strong><code>3.4.11</code></strong></td><td style="text-align:center;"><code>UC-024</code></td><td style="text-align:left;"><strong>Remove Agency Member</strong></td><td style="text-align:left;"><code>Owner</code></td><td style="text-align:left;">Xóa thành viên khỏi Agency (<code>/agency/:id/members</code>): thu hồi quyền truy cập vào Agency và các Workspace trực thuộc, nhưng <strong>bảo toàn nguyên vẹn mọi tài nguyên/bài viết/tư liệu</strong> mà người đó đã đóng góp (<code>BR-19</code>, <code>BR-21</code>).</td></tr><tr><td style="text-align:center;"><strong><code>3.4.12</code></strong></td><td style="text-align:center;"><code>UC-025</code></td><td style="text-align:left;"><strong>List Workspace</strong></td><td style="text-align:left;"><code>Owner</code>, <code>Manager</code>, <code>Creator</code>, <code>Client</code></td><td style="text-align:left;">Xem danh sách các Workspace (<code>/agency/:id/workspaces</code>): <code>Owner</code> thấy toàn bộ Workspace của Agency; <code>Manager</code>, <code>Creator</code>, <code>Client</code> chỉ thấy các Workspace mình được gán tham gia (<code>BR-20</code>).</td></tr><tr><td style="text-align:center;"><strong><code>3.4.13</code></strong></td><td style="text-align:center;"><code>UC-026</code></td><td style="text-align:left;"><strong>View Workspace Dashboard</strong></td><td style="text-align:left;"><code>Owner</code>, <code>Manager</code>, <code>Creator</code>, <code>Client</code></td><td style="text-align:left;">Xem bảng điều khiển tổng quan của từng Workspace (<code>/workspaces/:id/dashboard</code>): thống kê công việc theo trạng thái, lịch đăng bài sắp tới, tiến độ chiến dịch và mức dùng AI Credit (hiển thị <code>Personal Quick Launchpad</code> ở chế độ <code>PERSONAL</code>).</td></tr><tr><td style="text-align:center;"><strong><code>3.4.14</code></strong></td><td style="text-align:center;"><code>UC-027</code></td><td style="text-align:left;"><strong>Create Workspace</strong></td><td style="text-align:left;"><code>Owner</code></td><td style="text-align:left;">Tạo mới Workspace trực thuộc Agency (<code>/agency/:id/workspaces/new</code>): bắt buộc gán ít nhất 01 <code>Manager</code> (<code>BR-21</code>), cấu hình Tên, Mô tả, Múi giờ chuẩn IANA (<code>Timezone Configuration</code>, <code>BR-22</code>), chế độ <code>AGENCY</code>/<code>PERSONAL</code> và gói truyền thông ban đầu.</td></tr><tr><td style="text-align:center;"><strong><code>3.4.15</code></strong></td><td style="text-align:center;"><code>UC-028</code></td><td style="text-align:left;"><strong>View Workspace Profile</strong></td><td style="text-align:left;"><code>Owner</code>, <code>Manager</code>, <code>Creator</code>, <code>Client</code></td><td style="text-align:left;">Xem thông tin cấu hình chi tiết của Workspace (<code>/workspaces/:id/settings</code>) gồm Tên, Mô tả nhãn hàng, <code>Client</code> liên kết, Trạng thái và Múi giờ chuẩn IANA (<code>BR-20</code>, <code>BR-22</code>).</td></tr><tr><td style="text-align:center;"><strong><code>3.4.16</code></strong></td><td style="text-align:center;"><code>UC-029</code></td><td style="text-align:left;"><strong>Update Workspace Profile</strong></td><td style="text-align:left;"><code>Owner</code>, <code>Manager</code></td><td style="text-align:left;">Cập nhật Tên, Mô tả, Ảnh đại diện, Múi giờ chuẩn (<code>Timezone Configuration</code>, <code>BR-22</code>) và chuyển đổi chế độ <code>workspaceMode</code> (<code>PERSONAL ↔ AGENCY</code>) của Workspace.</td></tr><tr><td style="text-align:center;"><strong><code>3.4.17</code></strong></td><td style="text-align:center;"><code>UC-030</code></td><td style="text-align:left;"><strong>Delete Workspace</strong></td><td style="text-align:left;"><code>Owner</code></td><td style="text-align:left;">Xóa mềm Workspace (<code>/workspaces/:id/settings</code>): chỉ <code>Owner</code> được phép thực hiện, chuyển dữ liệu sang <code>INACTIVE</code> và cho phép khôi phục hoàn toàn trong vòng 30 ngày (<code>BR-15</code>, <code>BR-16</code>).</td></tr><tr><td style="text-align:center;"><strong><code>3.4.18</code></strong></td><td style="text-align:center;"><code>UC-031</code></td><td style="text-align:left;"><strong>Leave Workspace</strong></td><td style="text-align:left;"><code>Owner</code>, <code>Manager</code>, <code>Creator</code>, <code>Client</code></td><td style="text-align:left;">Rời khỏi một Workspace cụ thể mà vẫn giữ nguyên tư cách thành viên của Agency chủ quản (<code>BR-23</code>); nếu là <code>Manager</code> duy nhất đang hoạt động thì bắt buộc bổ nhiệm <code>Manager</code> thay thế trước khi rời (<code>BR-21</code>).</td></tr><tr><td style="text-align:center;"><strong><code>3.4.19</code></strong></td><td style="text-align:center;"><code>UC-032</code></td><td style="text-align:left;"><strong>Save Workspace Template</strong></td><td style="text-align:left;"><code>Owner</code></td><td style="text-align:left;">Lưu cấu hình chuẩn của một Workspace hiện hành (múi giờ, danh mục công việc mẫu, bộ hashtag, mẫu email, quy trình duyệt) thành Mẫu triển khai để tái sử dụng (<code>BR-24</code>).</td></tr><tr><td style="text-align:center;"><strong><code>3.4.20</code></strong></td><td style="text-align:center;"><code>UC-033</code></td><td style="text-align:left;"><strong>View Workspace Templates</strong></td><td style="text-align:left;"><code>Owner</code></td><td style="text-align:left;">Xem danh sách và chi tiết các mẫu cấu hình Workspace mặc định của hệ thống và các mẫu riêng do Agency đã lưu (<code>/agency/:id/workspace-templates</code>, <code>BR-24</code>).</td></tr><tr><td style="text-align:center;"><strong><code>3.4.21</code></strong></td><td style="text-align:center;"><code>UC-034</code></td><td style="text-align:left;"><strong>Apply Workspace Template</strong></td><td style="text-align:left;"><code>Owner</code></td><td style="text-align:left;">Áp dụng một mẫu cấu hình Workspace đã lưu vào Workspace mới hoặc hiện hành mà không làm ảnh hưởng dữ liệu lịch sử (<code>BR-22</code>, <code>BR-24</code>).</td></tr><tr><td style="text-align:center;"><strong><code>3.4.22</code></strong></td><td style="text-align:center;"><code>UC-035</code></td><td style="text-align:left;"><strong>Delete Workspace Template</strong></td><td style="text-align:left;"><code>Owner</code></td><td style="text-align:left;">Xóa mẫu cấu hình Workspace do Agency tự tạo khỏi thư viện mẫu; các Workspace đã áp dụng mẫu đó trước đây không bị ảnh hưởng (<code>BR-24</code>).</td></tr><tr><td style="text-align:center;"><strong><code>3.4.23</code></strong></td><td style="text-align:center;"><code>UC-036</code></td><td style="text-align:left;"><strong>View Workspace Members</strong></td><td style="text-align:left;"><code>Owner</code>, <code>Manager</code>, <code>Creator</code>, <code>Client</code></td><td style="text-align:left;">Xem danh sách các thành viên đang tham gia trong Workspace (<code>/workspaces/:id/members</code>) kèm vai trò (<code>Manager</code>, <code>Creator</code>, <code>Client</code>), ngày tham gia và trạng thái hoạt động (<code>BR-20</code>, <code>BR-21</code>).</td></tr><tr><td style="text-align:center;"><strong><code>3.4.24</code></strong></td><td style="text-align:center;"><code>UC-037</code></td><td style="text-align:left;"><strong>Add Workspace Member</strong></td><td style="text-align:left;"><code>Owner</code>, <code>Manager</code></td><td style="text-align:left;">Thêm thành viên thuộc Agency (hoặc tài khoản <code>Client</code> đối tác) vào Workspace và gán vai trò cụ thể (<code>MANAGER</code>, <code>CREATOR</code> hoặc <code>CLIENT</code>, <code>BR-20</code>).</td></tr><tr><td style="text-align:center;"><strong><code>3.4.25</code></strong></td><td style="text-align:center;"><code>UC-038</code></td><td style="text-align:left;"><strong>Update Workspace Member Role</strong></td><td style="text-align:left;"><code>Owner</code>, <code>Manager</code></td><td style="text-align:left;">Cập nhật vai trò của thành viên trong Workspace (ví dụ giữa <code>CREATOR</code> và <code>MANAGER</code>), đảm bảo luôn duy trì ít nhất 01 <code>Manager</code> đang hoạt động (<code>BR-21</code>).</td></tr><tr><td style="text-align:center;"><strong><code>3.4.26</code></strong></td><td style="text-align:center;"><code>UC-039</code></td><td style="text-align:left;"><strong>Remove Workspace Member</strong></td><td style="text-align:left;"><code>Owner</code>, <code>Manager</code></td><td style="text-align:left;">Xóa thành viên khỏi Workspace (<code>/workspaces/:id/members</code>): người bị xóa mất quyền truy cập Workspace đó nhưng tài nguyên đã đóng góp được giữ nguyên và họ vẫn thuộc Agency (<code>BR-19</code>, <code>BR-20</code>, <code>BR-21</code>).</td></tr></tbody></table><hr><h2 id="_2-quy-tac-nghiep-vu-cot-loi-cua-agency-workspace" tabindex="-1">2. Quy tắc Nghiệp vụ Cốt lõi của <code>Agency</code> &amp; <code>Workspace</code> <a class="header-anchor" href="#_2-quy-tac-nghiep-vu-cot-loi-cua-agency-workspace" aria-label="Permalink to &quot;2. Quy tắc Nghiệp vụ Cốt lõi của `Agency` &amp; `Workspace`&quot;">​</a></h2><ol><li><strong>Một <code>Owner</code> duy nhất cho mỗi <code>Agency</code> (<code>BR-15</code>)</strong>: Quyền sở hữu gắn cố định qua <code>agencies.owner_id</code>. Khi người dùng cá nhân sử dụng chế độ <code>Personal Studio</code>, hệ thống tự động khởi tạo một <code>Personal Hub Agency</code> ngầm mà người đó làm <code>Owner</code>.</li><li><strong>Bảo toàn tài sản chung &amp; Xóa mềm 30 ngày (<code>BR-16</code>, <code>BR-19</code>)</strong>: <ul><li>Xóa Agency (<code>3.4.6</code>) và xóa Workspace (<code>3.4.17</code>) đều là xóa mềm bảo lưu 30 ngày trước khi hết hạn lưu trữ.</li><li>Khi thành viên rời hoặc bị gỡ khỏi Agency/Workspace (<code>3.4.11</code>, <code>3.4.18</code>, <code>3.4.26</code>), toàn bộ bài viết, tư liệu và lịch sử công việc do họ tạo vẫn thuộc quyền sở hữu của Agency/Workspace.</li></ul></li><li><strong>Ràng buộc <code>Manager</code> tối thiểu &amp; Đồng bộ Múi giờ (<code>BR-21</code>, <code>BR-22</code>)</strong>: <ul><li>Mỗi Workspace đang hoạt động bắt buộc luôn có ít nhất 01 <code>Manager</code> (<code>ACTIVE</code>).</li><li>Trường <code>Timezone Configuration</code> theo chuẩn IANA (<code>Asia/Ho_Chi_Minh</code>, <code>America/New_York</code>...) tự động chuẩn hóa mọi mốc hạn chót công việc (<code>3.6.5</code>) và lịch xuất bản bài đăng (<code>3.8.6</code>) theo khu vực chiến dịch.</li></ul></li><li><strong>Chuyển đổi linh hoạt <code>PERSONAL ↔ AGENCY</code> (<code>3.4.16 Update Workspace Profile</code>)</strong>: <ul><li>Cho phép nâng cấp không gian <code>PERSONAL</code> lên <code>AGENCY</code> bất kỳ lúc nào mà giữ nguyên 100% dữ liệu; chiều thu gọn từ <code>AGENCY</code> về <code>PERSONAL</code> chỉ mở khi Workspace không có <code>Client</code> đang hoạt động.</li></ul></li></ol><hr><h2 id="_3-bang-tham-chieu-quy-tac-nghiep-vu-br-15-–-br-24-br-58" tabindex="-1">3. Bảng Tham chiếu Quy tắc Nghiệp vụ (<code>BR-15</code> – <code>BR-24</code>, <code>BR-58</code>) <a class="header-anchor" href="#_3-bang-tham-chieu-quy-tac-nghiep-vu-br-15-–-br-24-br-58" aria-label="Permalink to &quot;3. Bảng Tham chiếu Quy tắc Nghiệp vụ (`BR-15` – `BR-24`, `BR-58`)&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:center;">Mã BR</th><th style="text-align:left;">Tên Quy tắc</th><th style="text-align:left;">Quy định Ràng buộc Cụ thể</th><th style="text-align:left;">FR Áp dụng</th></tr></thead><tbody><tr><td style="text-align:center;"><code>BR-15</code></td><td style="text-align:left;"><strong>Chủ sở hữu Duy nhất cấp Agency</strong></td><td style="text-align:left;">Mỗi <code>Agency</code> có đúng 01 <code>Owner</code> duy nhất (<code>agencies.owner_id</code>); chỉ <code>Owner</code> được sửa hồ sơ công ty, xóa mềm công ty/Workspace, quản lý mẫu Workspace và thanh toán gói cước.</td><td style="text-align:left;"><code>3.4.1</code>–<code>3.4.6</code>, <code>3.4.17</code>, <code>3.4.19</code>–<code>3.4.22</code></td></tr><tr><td style="text-align:center;"><code>BR-16</code></td><td style="text-align:left;"><strong>Bảo lưu Xóa Mềm 30 Ngày</strong></td><td style="text-align:left;">Xóa <code>Agency</code> (<code>3.4.6</code>) hoặc <code>Workspace</code> (<code>3.4.17</code>) chuyển trạng thái sang <code>INACTIVE</code> / <code>DELETED_PENDING</code>, khóa tạo tác vụ mới nhưng cho phép khôi phục nguyên trạng trong vòng <strong>30 ngày</strong>.</td><td style="text-align:left;"><code>3.4.6</code>, <code>3.4.17</code></td></tr><tr><td style="text-align:center;"><code>BR-17</code></td><td style="text-align:left;"><strong>Thời hạn Lời mời 30 Ngày</strong></td><td style="text-align:left;">Lời mời gia nhập <code>Agency</code> (<code>agency_invitations</code>) sử dụng token một lần và tự động hết hạn (<code>EXPIRED</code>) sau <strong>30 ngày</strong> nếu người nhận chưa phản hồi.</td><td style="text-align:left;"><code>3.4.7</code>–<code>3.4.10</code></td></tr><tr><td style="text-align:center;"><code>BR-18</code></td><td style="text-align:left;"><strong>Ràng buộc Định danh Người nhận Lời mời</strong></td><td style="text-align:left;">Chỉ tài khoản có email khớp với email lời mời và lời mời đang ở trạng thái <code>PENDING</code> mới được thực hiện <code>Accept</code> (<code>3.4.9</code>) hoặc <code>Decline</code> (<code>3.4.10</code>).</td><td style="text-align:left;"><code>3.4.8</code>–<code>3.4.10</code></td></tr><tr><td style="text-align:center;"><code>BR-19</code></td><td style="text-align:left;"><strong>Bảo toàn Tài sản Sáng tạo khi Rời Nhóm</strong></td><td style="text-align:left;">Khi xóa thành viên khỏi <code>Agency</code> (<code>3.4.11</code>), rời <code>Workspace</code> (<code>3.4.18</code>) hoặc xóa thành viên khỏi <code>Workspace</code> (<code>3.4.26</code>), mọi bài đăng, công việc, bình luận và tư liệu người đó đã tạo vẫn thuộc quyền sở hữu của <code>Agency</code>/<code>Workspace</code>.</td><td style="text-align:left;"><code>3.4.11</code>, <code>3.4.18</code>, <code>3.4.26</code></td></tr><tr><td style="text-align:center;"><code>BR-20</code></td><td style="text-align:left;"><strong>Cô lập Đa Thuê bao (<code>workspaceId</code> Isolation)</strong></td><td style="text-align:left;">Mọi truy vấn dữ liệu cấp <code>Workspace</code> chỉ trả về bản ghi của <code>Workspace</code> mà người dùng có tư cách thành viên hợp lệ (hoặc là <code>Owner</code> của <code>Agency</code> chủ quản).</td><td style="text-align:left;"><code>3.4.12</code>–<code>3.4.16</code>, <code>3.4.23</code>–<code>3.4.26</code></td></tr><tr><td style="text-align:center;"><code>BR-21</code></td><td style="text-align:left;"><strong>Bắt buộc Tối thiểu 01 <code>Manager</code> Hoạt động</strong></td><td style="text-align:left;">Mọi <code>Workspace</code> đang hoạt động bắt buộc duy trì ít nhất <strong>01 <code>Manager</code> (<code>ACTIVE</code>)</strong>; chặn thao tác tự rời nhóm, hạ vai trò hoặc xóa thành viên nếu đó là <code>Manager</code> cuối cùng.</td><td style="text-align:left;"><code>3.4.11</code>, <code>3.4.14</code>, <code>3.4.18</code>, <code>3.4.25</code>, <code>3.4.26</code></td></tr><tr><td style="text-align:center;"><code>BR-22</code></td><td style="text-align:left;"><strong>Chuẩn hóa Múi giờ IANA theo Workspace</strong></td><td style="text-align:left;">Cấu hình múi giờ (<code>workspaces.timezone</code>, ví dụ <code>Asia/Ho_Chi_Minh</code>) là mốc quy chiếu duy nhất cho hạn chót công việc, lịch xuất bản bài đăng và bản tin email trong Workspace.</td><td style="text-align:left;"><code>3.4.14</code>–<code>3.4.16</code>, <code>3.4.21</code></td></tr><tr><td style="text-align:center;"><code>BR-23</code></td><td style="text-align:left;"><strong>Tách biệt Tư cách Thành viên Agency và Workspace</strong></td><td style="text-align:left;">Thành viên bấm <code>Leave Workspace</code> (<code>3.4.18</code>) chỉ rút khỏi không gian làm việc đó, vẫn giữ nguyên tư cách thành viên trong <code>agency_members</code> và các <code>Workspace</code> khác.</td><td style="text-align:left;"><code>3.4.18</code></td></tr><tr><td style="text-align:center;"><code>BR-24</code></td><td style="text-align:left;"><strong>Tính Độc lập của Mẫu Cấu hình (<code>WorkspaceTemplate</code>)</strong></td><td style="text-align:left;">Lưu, áp dụng hoặc xóa <code>WorkspaceTemplate</code> hoạt động theo cơ chế sao chép cấu hình (<code>copy-on-apply</code>), tuyệt đối không ghi đè ngược dữ liệu lịch sử của các <code>Workspace</code> đã áp dụng trước đó.</td><td style="text-align:left;"><code>3.4.19</code>–<code>3.4.22</code></td></tr><tr><td style="text-align:center;"><code>BR-58</code></td><td style="text-align:left;"><strong>Giới hạn Định mức theo Gói Cước</strong></td><td style="text-align:left;">Số lượng <code>Workspace</code> hoạt động tối đa, số lượng thành viên và dung lượng kho lưu trữ chịu sự kiểm soát trực tiếp bởi hạn mức gói đăng ký hiện hành của <code>Owner</code>.</td><td style="text-align:left;"><code>3.4.3</code>, <code>3.4.7</code>, <code>3.4.14</code>, <code>3.9.1</code></td></tr></tbody></table><hr><h2 id="_4-so-đo-phan-tang-to-chuc-luong-gia-nhap-thanh-vien" tabindex="-1">4. Sơ đồ Phân tầng Tổ chức &amp; Luồng Gia nhập Thành viên <a class="header-anchor" href="#_4-so-đo-phan-tang-to-chuc-luong-gia-nhap-thanh-vien" aria-label="Permalink to &quot;4. Sơ đồ Phân tầng Tổ chức &amp; Luồng Gia nhập Thành viên&quot;">​</a></h2><div class="language-mermaid vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">mermaid</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">flowchart TD</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    OWN[&quot;Owner&quot;] --&gt;|&quot;3.4.3 Create Agency&quot;| AG[&quot;Agency / Personal Hub&lt;br/&gt;(PostgreSQL: agencies)&quot;]</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    OWN --&gt;|&quot;3.4.7 Invite (30d TTL)&quot;| INV[&quot;AgencyInvitation&lt;br/&gt;(PENDING → ACCEPTED / DECLINED)&quot;]</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    INV --&gt;|&quot;3.4.9 Accept&quot;| AM[&quot;AgencyMember&lt;br/&gt;(agency_members)&quot;]</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    AG --&gt;|&quot;3.4.14 Create Workspace&lt;br/&gt;(≥1 Manager + IANA Timezone)&quot;| WS[&quot;Workspace&lt;br/&gt;(workspaceMode: AGENCY | PERSONAL)&quot;]</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    AM --&gt;|&quot;3.4.24 Add Member&quot;| WM[&quot;WorkspaceMember&lt;br/&gt;(MANAGER | CREATOR)&quot;]</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    CP[&quot;ClientProfile (Reusable)&quot;] --&gt;|&quot;3.4.24 Link Client&quot;| WMC[&quot;WorkspaceMember&lt;br/&gt;(role = CLIENT)&quot;]</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    WS --- WM</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    WS --- WMC</span></span></code></pre></div><hr><h2 id="_5-anh-xa-co-so-du-lieu-kiem-soat-truy-cap" tabindex="-1">5. Ánh xạ Cơ sở Dữ liệu &amp; Kiểm soát Truy cập <a class="header-anchor" href="#_5-anh-xa-co-so-du-lieu-kiem-soat-truy-cap" aria-label="Permalink to &quot;5. Ánh xạ Cơ sở Dữ liệu &amp; Kiểm soát Truy cập&quot;">​</a></h2><ul><li><strong>PostgreSQL (<code>brandhub-business-service</code>)</strong>: <code>agencies</code>, <code>agency_members</code>, <code>agency_invitations</code>, <code>workspaces</code>, <code>workspace_members</code>, <code>workspace_invitations</code>, <code>workspace_templates</code>, <code>client_profiles</code> (xem chi tiết tại <a href="./../database/schema/database-strategy.html">Database Strategy V2</a>).</li><li><strong>Kiểm tra phân quyền ngữ cảnh</strong>: Vai trò vận hành (<code>Manager</code>, <code>Creator</code>, <code>Client</code>) được tra cứu theo cặp <code>(workspace_id, user_id)</code> trên mỗi yêu cầu API, trong khi <code>Owner</code> được suy ra trực tiếp từ <code>agencies.owner_id</code> (xem <a href="./10-roles-permissions-matrix.html">10 - Roles &amp; Permissions Matrix</a>).</li></ul>',17)])])}const u=t(n,[["render",a]]);export{y as __pageData,u as default};
